.getlist li{list-style:none;display:flex;gap:11px;align-items:flex-start;background:var(--glass);border:1px solid var(--line);border-radius:13px;padding:14px 16px}
.getlist .tk{width:24px;height:24px;border-radius:7px;background:linear-gradient(135deg,var(--amber),#f7a80a);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.getlist .tk svg{width:14px;height:14px;color:#231704}
.getlist b{font-family:var(--fdisp);font-size:.96rem}.getlist small{display:block;color:var(--mut);font-size:.82rem;margin-top:2px}
@media(max-width:640px){.getlist{grid-template-columns:1fr}}
