.areas{display:flex;flex-wrap:wrap;gap:9px;margin-top:6px}
.areas span{background:var(--glass);border:1px solid var(--line);border-radius:999px;padding:7px 14px;font-family:var(--fdisp);font-weight:600;font-size:.86rem;color:var(--ink2)}
.note-block{background:var(--glass);border:1px solid var(--line2);border-left:3px solid var(--amber);border-radius:12px;padding:16px 18px;color:var(--ink2);font-size:.96rem;max-width:760px}
.statrow{display:flex;flex-wrap:wrap;gap:14px;margin-top:6px}
.statrow .st{background:var(--glass);border:1px solid var(--line);border-radius:14px;padding:16px 20px;min-width:150px}
.statrow .st b{display:block;font-family:var(--fdisp);font-weight:800;font-size:1.7rem;background:linear-gradient(100deg,#ffe08a,#f7a80a);-webkit-background-clip:text;background-clip:text;color:transparent}
.statrow .st span{font-size:.84rem;color:var(--mut)}
.cta-ph{position:absolute;right:clamp(16px,3vw,44px);top:50%;transform:translateY(-50%);width:min(300px,36%);aspect-ratio:4/3;object-fit:contain;z-index:1;pointer-events:none;filter:drop-shadow(0 14px 22px rgba(0,0,0,.4))}
@media(max-width:820px){.cta-ph{display:none}}

