/* comparison table */
.cmp{width:100%;border-collapse:separate;border-spacing:0;border:1px solid var(--line);border-radius:16px;overflow:hidden;font-size:.96rem}
.cmp th,.cmp td{padding:15px 18px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}
.cmp thead th{background:var(--glass2);font-family:var(--fdisp);font-size:.82rem;letter-spacing:.04em;text-transform:uppercase;color:var(--ink)}
.cmp thead th.nifty{background:linear-gradient(120deg,rgba(247,168,10,.18),rgba(247,168,10,.08));color:var(--ink)}
.cmp td.nifty{background:rgba(247,168,10,.05)}
.cmp tbody tr:last-child td,.cmp tr:last-child td{border-bottom:0}
.cmp td:first-child{font-weight:600;color:var(--ink)}
.cmp .yes{color:var(--green-d,#5fa32e);font-weight:700}
.cmp .no{color:var(--mut)}
.cmp-wrap{overflow-x:auto;border-radius:16px}
/* faq */
.faq{display:grid;gap:12px;max-width:820px;margin:0 auto}
