@import url("https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&family=Inter:wght@400;500;600;700&display=swap");

ul,ol{list-style:revert;margin:revert;padding:revert}
li{list-style:revert}
img,svg,video{max-width:revert;height:revert;display:revert;vertical-align:revert}
button,input,select,textarea{font:revert;color:revert;background:revert;border:revert;margin:revert;padding:revert;text-align:revert;line-height:revert}
table{border-collapse:revert;text-indent:revert}
blockquote,figure,fieldset{margin:revert;padding:revert}
h1,h2,h3,h4,h5,h6{font-size:revert;font-weight:revert;margin:revert;line-height:revert}
p{margin:revert}
a{color:revert;text-decoration:revert}
hr{border:revert;height:revert;color:revert}

.nifty-part-header-1 * {box-sizing:border-box}
.nifty-part-header-1 {

  --amber:#f7a80a;--amber-l:#ffc247;--gold:#ffd874;--amber-d:#c47a08;
  --cyan:#f7a80a;--cyan-d:#c47a08;--violet:#f7a80a;--violet-d:#c47a08;
  --blue:#3b82f6;--blue-l:#7ab0ff;--pink:#f7a80a;--green:#34e0a1;
  --grad:linear-gradient(120deg,#ffd874,#f7a80a);
  --grad-b:linear-gradient(120deg,#7ab0ff,#3b82f6);
  --gcyan:rgba(247,168,10,.55);--gviolet:rgba(247,168,10,.42);
  --gut:clamp(18px,5vw,44px);
  --fdisp:'Sora',system-ui,sans-serif;--fbody:'Inter',system-ui,sans-serif;
  --r:18px;
}
.nifty-part-header-1 {
  --bg:#07080f;--bg2:#0b0d16;--bg3:#0e1018;
  --ink:#f4f6fb;--ink2:#c9cfdd;--mut:#8b93a8;
  --line:rgba(255,255,255,.10);--line2:rgba(255,255,255,.18);
  --glass:rgba(255,255,255,.045);--glass2:rgba(255,255,255,.08);
  --base:#0a0c15;--cream:#0c0e18;
  --hdrbg:#0a0d16;--hdrtext:#dbe2f5;--capbg:#0c0f1c;--menubg:#0d111d;
  --utilbg:#05060f;--utiltext:#9aa3c0;
  --shadow:0 24px 60px -28px rgba(0,0,0,.8);
  --glow:0 0 0 1px rgba(247,168,10,.3),0 18px 50px -18px rgba(247,168,10,.3),0 10px 40px -14px rgba(0,0,0,.5);
  --page-grad:radial-gradient(900px 600px at 12% -5%,rgba(247,168,10,.10),transparent 60%),radial-gradient(900px 620px at 92% 4%,rgba(59,130,246,.10),transparent 60%)}
.nifty-part-header-1 .rowlight {
  background:#f4f6fc;
  --ink:#0e1424;--ink2:#42506a;--mut:#697390;
  --line:rgba(14,20,36,.10);--line2:rgba(14,20,36,.16);
  --glass:#ffffff;--glass2:#eef2f9;
  --base:#f4f6fc;--cream:#f4f6fc;
  --glow:0 0 0 1px rgba(247,168,10,.35),0 18px 40px -20px rgba(247,168,10,.3),0 10px 30px -16px rgba(20,30,60,.15);
  color:var(--ink)}
.nifty-part-header-1 .rowlight .vc, .nifty-part-header-1 .rowlight .svc, .nifty-part-header-1 .rowlight .rev, .nifty-part-header-1 .rowlight .plan, .nifty-part-header-1 .rowlight .ind, .nifty-part-header-1 .rowlight .pstep {
  box-shadow:0 14px 36px -22px rgba(20,30,60,.3)}
.nifty-part-header-1 {scroll-behavior:smooth}
.nifty-part-header-1 {margin:0;background:var(--bg);background-image:var(--page-grad);background-attachment:fixed;
  color:var(--ink);min-height:100vh;font-family:var(--fbody);
  font-size:16.5px;line-height:1.62;-webkit-font-smoothing:antialiased;overflow-x:hidden}
.nifty-part-header-1 img {max-width:100%;display:block}
.nifty-part-header-1 svg {width:18px;height:18px;flex-shrink:0}
.nifty-part-header-1 a {color:inherit;text-decoration:none}
.nifty-part-header-1 h1, .nifty-part-header-1 h2, .nifty-part-header-1 h3, .nifty-part-header-1 h4 {font-family:var(--fdisp);line-height:1.06;margin:0;letter-spacing:-.02em;font-weight:800}
.nifty-part-header-1 p {margin:0 0 1em}
.nifty-part-header-1 .wrap {max-width:1240px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.nifty-part-header-1 .eyebrow {font-family:var(--fdisp);font-weight:700;font-size:.78rem;letter-spacing:.18em;
  text-transform:uppercase;color:var(--cyan)}
.nifty-part-header-1 .k-amber {background:linear-gradient(100deg,#ffd874,#ffb23a 50%,#f7a80a);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 16px rgba(247,168,10,.35))}
.nifty-part-header-1 .k-green {background:var(--grad-b);-webkit-background-clip:text;background-clip:text;color:transparent}
.nifty-part-header-1 .btn {display:inline-flex;align-items:center;gap:.5em;font-family:var(--fdisp);font-weight:700;
  font-size:.98rem;padding:.85em 1.5em;border-radius:999px;border:0;cursor:pointer;
  transition:transform .18s,box-shadow .18s,background .18s,border-color .18s;white-space:nowrap;position:relative}
.nifty-part-header-1 .btn svg {width:18px;height:18px}
.nifty-part-header-1 .btn-amber {background:linear-gradient(135deg,#ffc247,#f7a80a);color:#231704;
  box-shadow:0 0 26px -4px rgba(247,168,10,.6),0 0 46px -12px rgba(247,168,10,.45)}
.nifty-part-header-1 .btn-amber:hover {transform:translateY(-3px);box-shadow:0 0 36px -2px rgba(247,168,10,.8),0 0 60px -10px rgba(247,168,10,.5)}
.nifty-part-header-1 .btn-ghost {background:var(--glass);color:#fff;border:1px solid var(--line2);backdrop-filter:blur(8px)}
.nifty-part-header-1 .btn-ghost:hover {border-color:var(--cyan);transform:translateY(-3px);box-shadow:0 0 24px -6px var(--gcyan)}
.nifty-part-header-1 .btn-dark {background:var(--glass2);color:#fff;border:1px solid var(--line)}
.nifty-part-header-1 .btn-dark:hover {transform:translateY(-3px);border-color:var(--violet);box-shadow:0 0 24px -6px var(--gviolet)}
.nifty-part-header-1 .btn-lg {padding:1.05em 1.9em;font-size:1.05rem}
.nifty-part-header-1 .rv, .nifty-part-header-1 .rv2, .nifty-part-header-1 .rv3 {opacity:1}
.nifty-part-header-1 .rv {animation:rvIn .8s both}
.nifty-part-header-1 .rv2 {animation:rvIn .8s .12s both}
.nifty-part-header-1 .rv3 {animation:rvIn .8s .24s both}
@keyframes rvIn {from{transform:translateY(22px)}to{transform:none}}
@media (prefers-reduced-motion:reduce) {.nifty-part-header-1 .rv, .nifty-part-header-1 .rv2, .nifty-part-header-1 .rv3, .nifty-part-header-1 .aurora, .nifty-part-header-1 .marq-row, .nifty-part-header-1 .spin, .nifty-part-header-1 .pulse, .nifty-part-header-1 .stage-char, .nifty-part-header-1 .stage-ring, .nifty-part-header-1 .fcard, .nifty-part-header-1 .fc-ico, .nifty-part-header-1 .orb {animation:none!important}
.nifty-part-header-1 {scroll-behavior:auto}}
.nifty-part-header-1 .util {background:var(--utilbg);color:var(--utiltext);font-size:.82rem;border-bottom:1px solid var(--line)}
.nifty-part-header-1 .util .wrap {display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:8px;padding-bottom:8px}
.nifty-part-header-1 .util a {color:var(--utiltext);transition:color .15s}
.nifty-part-header-1 .util a:hover {color:var(--amber)}
.nifty-part-header-1 .util-l, .nifty-part-header-1 .util-r {display:flex;align-items:center;gap:18px;flex-wrap:wrap}
.nifty-part-header-1 .util-l a {font-weight:500}
.nifty-part-header-1 .util-ph {color:var(--ink)!important;font-family:var(--fdisp);font-weight:700;display:inline-flex;align-items:center;gap:6px}
.nifty-part-header-1 .util-ph svg {width:15px;height:15px;color:var(--cyan)}
.nifty-part-header-1 .util-login {display:inline-flex;align-items:center;gap:6px}
.nifty-part-header-1 .util-login svg {width:14px;height:14px}
@media(max-width:820px) {.nifty-part-header-1 .util-l {display:none}}
.nifty-part-header-1 .hdr {position:sticky;top:0;z-index:1000}
