/* image placeholder frame w/ meta */
.ph-img{display:block;width:100%;height:auto;border-radius:16px}
.ph-img.showcase{max-width:1000px;margin:0 auto}
.phmeta{position:absolute;left:12px;bottom:12px;right:12px;display:flex;flex-direction:column;gap:2px;background:rgba(8,11,20,.72);backdrop-filter:blur(6px);border:1px solid var(--line);border-radius:10px;padding:8px 11px;font-size:.72rem;color:var(--mut)}
